-- Normalize stable metric/health fields. Keep malformed and unknown legacy values.
BEGIN IMMEDIATE;
ALTER TABLE "MetricLog" ADD COLUMN "type" TEXT;
ALTER TABLE "MetricLog" ADD COLUMN "exercise" TEXT;
ALTER TABLE "MetricLog" ADD COLUMN "weight" REAL;
ALTER TABLE "MetricLog" ADD COLUMN "reps" INTEGER;
ALTER TABLE "MetricLog" ADD COLUMN "sets" INTEGER;
ALTER TABLE "MetricLog" ADD COLUMN "notes" TEXT;
ALTER TABLE "MetricLog" ADD COLUMN "photoUrl" TEXT;
ALTER TABLE "MetricLog" ADD COLUMN "label" TEXT;
ALTER TABLE "health_profiles" ADD COLUMN "posture" TEXT;
ALTER TABLE "health_profiles" ADD COLUMN "broncoTest" TEXT;
ALTER TABLE "health_profiles" ADD COLUMN "diets" TEXT;
ALTER TABLE "health_profiles" ADD COLUMN "hobbies" TEXT;
CREATE TABLE "MetricMeasurement" (
 "id" TEXT NOT NULL PRIMARY KEY,
 "metricLogId" TEXT NOT NULL,
 "container" TEXT NOT NULL,
 "key" TEXT NOT NULL,
 "valueType" TEXT NOT NULL,
 "value" REAL,
 "stringValue" TEXT,
 "booleanValue" BOOLEAN,
 "unit" TEXT,
 CONSTRAINT "MetricMeasurement_metricLogId_fkey" FOREIGN KEY ("metricLogId") REFERENCES "MetricLog"("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE TABLE "HealthSense" (
 "id" TEXT NOT NULL PRIMARY KEY,
 "profileId" TEXT NOT NULL,
 "key" TEXT NOT NULL,
 "level" REAL,
 "note" TEXT,
 "currentPower" TEXT,
 "targetPower" TEXT,
 "path" TEXT,
 "color" TEXT,
 "exercises" TEXT,
 "data" TEXT,
 CONSTRAINT "HealthSense_profileId_fkey" FOREIGN KEY ("profileId") REFERENCES "health_profiles"("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE TABLE "HealthSpecialized" (
 "id" TEXT NOT NULL PRIMARY KEY,
 "profileId" TEXT NOT NULL,
 "position" INTEGER NOT NULL,
 "name" TEXT,
 "score" REAL,
 "color" TEXT,
 "data" TEXT,
 CONSTRAINT "HealthSpecialized_profileId_fkey" FOREIGN KEY ("profileId") REFERENCES "health_profiles"("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE TABLE "HealthRecoveryMetric" (
 "id" TEXT NOT NULL PRIMARY KEY,
 "profileId" TEXT NOT NULL,
 "clientId" TEXT,
 "position" INTEGER NOT NULL,
 "name" TEXT,
 "valueType" TEXT,
 "value" REAL,
 "stringValue" TEXT,
 "booleanValue" BOOLEAN,
 "status" TEXT,
 "data" TEXT,
 CONSTRAINT "HealthRecoveryMetric_profileId_fkey" FOREIGN KEY ("profileId") REFERENCES "health_profiles"("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE UNIQUE INDEX "MetricMeasurement_metricLogId_container_key_key" ON "MetricMeasurement"("metricLogId","container","key");
CREATE INDEX "MetricMeasurement_key_value_idx" ON "MetricMeasurement"("key","value");
CREATE UNIQUE INDEX "HealthSense_profileId_key_key" ON "HealthSense"("profileId","key");
CREATE UNIQUE INDEX "HealthSpecialized_profileId_position_key" ON "HealthSpecialized"("profileId","position");
CREATE UNIQUE INDEX "HealthRecoveryMetric_profileId_position_key" ON "HealthRecoveryMetric"("profileId","position");
UPDATE "MetricLog" SET "type"=json_extract((CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END), '$.type'), "data"=json_remove("data",'$.type') WHERE json_type((CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END), '$.type') IN ('text','null');
