UPDATE "MetricLog" SET "reps"=CASE WHEN json_type((CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END), '$.reps')='null' THEN NULL ELSE CAST(json_extract((CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END), '$.reps') AS INTEGER) END, "data"=json_remove("data",'$.reps') WHERE (json_type((CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END), '$.reps')='null' OR (json_type((CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END), '$.reps') IN ('integer','real','text') AND (CASE WHEN typeof(json_extract((CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END), '$.reps')) IN ('integer','real') THEN abs(json_extract((CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END), '$.reps'))<=1.7976931348623157e308 WHEN typeof(json_extract((CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END), '$.reps'))='text' AND json_valid(json_extract((CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END), '$.reps')) THEN CASE WHEN json_type(json_extract((CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END), '$.reps')) IN ('integer','real') THEN abs(CAST(json_extract((CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END), '$.reps') AS REAL))<=1.7976931348623157e308 ELSE 0 END ELSE 0 END) AND CAST(json_extract((CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END), '$.reps') AS REAL)=CAST(json_extract((CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END), '$.reps') AS INTEGER) AND CAST(json_extract((CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END), '$.reps') AS REAL) BETWEEN 0 AND 2147483647));
