bject' THEN "data" ELSE '{}' END ELSE '{}' END), '$.sets') AS INTEGER) AND CAST(json_extract((CASE WHEN json_valid("data") THEN CASE WHEN json_type("data")='object' THEN "data" ELSE '{}' END ELSE '{}' END), '$.sets') AS REAL) BETWEEN 0 AND 2147483647));
