 AND (j.key NOT IN ('height','weight','bodyFat','leanMass','skeletalMuscle','bodyWater','boneMass','visceralFat','chest','waist','shoulders','shoulderBreadth','bideltoidBreadth','chestDepth','underbust','arms','forearm','wrist','elbow','neck','hips','highHip','pelvicBreadth','glutes','thighs','calves','ankle','torsoLength','sittingHeight','upperArm','lowerArm','handLength','legLength','upperLegLength','lowerLegLength','inseam','neckLength','footLength','headCirc','faceWidth','faceHeight','eyeSpacing','earLength','earWidth','noseLength','noseWidth','anatomyLengthCm','anatomyGirthCm','d_size','d_length','d_girth','leftShoulder','rightShoulder','leftUpperArm','rightUpperArm','leftForearm','rightForearm','leftWrist','rightWrist','leftThigh','rightThigh','leftCalf','rightCalf','leftHip','rightHip','headTiltAngle','pelvicTilt','shoulderRounding','shoulderTilt','spineCurvature','hipRotation','kneeAlignment','leftKneeAngle','rightKneeAngle','leftFootRotation','rightFootRotation','brow_depth','nose_bridge_width','nose_tip_size','ear_prominence','jaw_width','chin_projection','lip_fullness','eye_size') OR j.type='null' OR (j.type IN ('integer','real','text') AND (CASE WHEN typeof(j.atom) IN ('integer','real') THEN abs(j.atom)<=1.7976931348623157e308 WHEN typeof(j.atom)='text' AND json_valid(j.atom) THEN CASE WHEN json_type(j.atom) IN ('integer','real') THEN abs(CAST(j.atom AS REAL))<=1.7976931348623157e308 ELSE 0 END ELSE 0 END)))
 AND (j.type NOT IN ('integer','real') OR abs(j.atom)<=1.7976931348623157e308);
